<script setup>
import { nextTick, reactive, ref, watch } from 'vue'
import { links } from '../content.js'
import ArrowIcon from '../components/ArrowIcon.vue'
import StarDoodle from '../components/StarDoodle.vue'
const fields = reactive({ name: '', email: '', topic: 'Finding a workshop', message: '' })
const errors = reactive({})
const draft = ref('')
const copyStatus = ref('')
watch(fields, () => { draft.value = ''; copyStatus.value = ''; Object.keys(errors).forEach(key => delete errors[key]) })
async function prepare() {
  Object.keys(errors).forEach(key => delete errors[key])
  if (!fields.name.trim()) errors.name = 'Please enter your name.'
  if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(fields.email.trim())) errors.email = 'Please enter a valid email address for your draft.'
  if (fields.message.trim().length < 10) errors.message = 'Add a little more detail (at least 10 characters).'
  if (Object.keys(errors).length) { draft.value = ''; await nextTick(); document.getElementById(`contact-${Object.keys(errors)[0]}`)?.focus(); return }
  draft.value = `Hi Learn Bhangra Melbourne!\n\nI’m ${fields.name.trim()}. I’m getting in touch about: ${fields.topic}.\n\n${fields.message.trim()}\n\nMy reply email: ${fields.email.trim()}`
  await nextTick(); document.getElementById('draft-heading')?.focus({ preventScroll: true }); document.getElementById('draft-panel')?.scrollIntoView({ block: 'nearest', behavior: window.matchMedia('(prefers-reduced-motion: reduce)').matches ? 'auto' : 'smooth' })
}
async function copy() {
  try { await navigator.clipboard.writeText(draft.value); copyStatus.value = 'Draft copied. Paste it into an Instagram message when you’re ready.' } catch { document.getElementById('contact-draft')?.select(); copyStatus.value = 'Select and copy the draft below, then paste it into Instagram.' }
}
</script>
<template>
  <section class="page-hero pink"><p class="eyebrow">FIRST STEP? SAY HELLO.</p><h1>Let’s talk.<br /><em>Then let’s dance.</em></h1><p>Questions, collaborations, or a little first-class encouragement.<br />We’re all ears.</p><StarDoodle class="page-hero-doodle" /></section>
  <section class="contact-section section-pad"><aside class="contact-aside"><p class="eyebrow">THE REAL WAY TO REACH US</p><h2>Slide into<br />the <em>good energy.</em></h2><p>Instagram is the official contact channel. Use the form to organise your thoughts, then copy your draft and send it there.</p><a :href="links.instagram" class="button button-dark" target="_blank" rel="noopener noreferrer">Open Instagram <ArrowIcon /><span class="sr-only"> (new tab)</span></a><p class="contact-handle">@learnbhangra_melbourne</p><div class="contact-note"><span aria-hidden="true">↳</span><p>Nothing is sent from this form.<br />Your draft stays in this page. Avoid sharing sensitive information.</p></div></aside><form class="contact-form" novalidate @submit.prevent="prepare"><p class="eyebrow">MAKE A MESSAGE DRAFT</p><div class="form-row"><div class="form-field"><label for="contact-name">Your name <span>(required)</span></label><input id="contact-name" v-model="fields.name" autocomplete="name" maxlength="100" required :aria-invalid="!!errors.name" :aria-describedby="errors.name ? 'error-name' : undefined" placeholder="What should we call you?" /><p v-if="errors.name" id="error-name" class="field-error">{{ errors.name }}</p></div><div class="form-field"><label for="contact-email">Reply email <span>(required)</span></label><input id="contact-email" v-model="fields.email" type="email" autocomplete="email" maxlength="254" required :aria-invalid="!!errors.email" :aria-describedby="errors.email ? 'error-email' : undefined" placeholder="For your message draft" /><p v-if="errors.email" id="error-email" class="field-error">{{ errors.email }}</p></div></div><div class="form-field"><label for="contact-topic">What’s on your mind?</label><select id="contact-topic" v-model="fields.topic"><option>Finding a workshop</option><option>My first Bhangra class</option><option>Access & participation</option><option>Collaborations & community</option><option>Something else</option></select></div><div class="form-field"><label for="contact-message">Your message <span>(required)</span></label><textarea id="contact-message" v-model="fields.message" rows="5" maxlength="3000" required :aria-invalid="!!errors.message" :aria-describedby="errors.message ? 'error-message' : 'message-hint'" placeholder="Ask away. No question too small."></textarea><p v-if="errors.message" id="error-message" class="field-error">{{ errors.message }}</p><p id="message-hint" class="field-hint">At least 10 characters. Please don’t include sensitive information.</p></div><button class="button button-dark" type="submit">Prepare my message <ArrowIcon /></button><p class="form-disclaimer">No mailing list. No pretend “sent” message. Just a draft you control.</p><section v-if="draft" id="draft-panel" class="draft-panel"><h3 id="draft-heading" tabindex="-1">Ready for your final step.</h3><p>This message has <strong>not been sent</strong>. Copy it and send it through the official Instagram account.</p><label class="sr-only" for="contact-draft">Your message draft</label><textarea id="contact-draft" :value="draft" readonly rows="9"></textarea><div class="draft-actions"><button type="button" class="button button-dark" @click="copy">Copy draft <ArrowIcon /></button><a :href="links.instagram" class="text-link" target="_blank" rel="noopener noreferrer">Open Instagram ↗<span class="sr-only"> (new tab)</span></a></div><p v-if="copyStatus" role="status" class="copy-status">{{ copyStatus }}</p></section></form></section>
</template>
